	$name = sanitize_html_class( $name );

	// Graceful fallback: if a wp.org badge uses a glyph we haven't
	// bundled yet, render the awards star instead of an empty disc.
	if ( ! isset( $paths[ $name ] ) ) {
		$name = 'awards';
	}

	$entry = $paths[ $name ];
	if ( is_array( $entry ) ) {
		$view_box = $entry['viewBox'];
		$content  = $entry['content'];
	} else {
		$view_box = '0 0 20 20';
		$content  = $entry;
	}

	$defaults = array( 'width' => 20, 'height' => 20, 'class' => '' );
	$args     = wp_parse_args( $args, $defaults );
	$class    = trim( 'wcu-dashicon wcu-dashicon--' . $name . ' ' . $args['class'] );

	return sprintf(
		'<svg xmlns="http://www.w3.org/2000/svg" class="%1$s" width="%2$d" height="%3$d" viewBox="%4$s" fill="currentColor" aria-hidden="true">%5$s</svg>',
		esc_attr( $class ),
		(int) $args['width'],
		(int) $args['height'],
		esc_attr( $view_box ),
		$content
	);
}

/**
 * Resolve which icon to render for a wp.org badge.
 *
 * Some badges use a CSS background-image data-URI on wp.org rather than
 * a font glyph (Campus Connect Participant, Credits Graduate, Credits
 * Mentor). Those have no `dashicons-{name}` class in the markup, so the
 * scraped `$dashicon` field is empty. For them we rely on the badge slug
 * to look up a custom SVG we ship in `wcu_get_dashicon_svg()`.
 *
 * Resolution order:
 *   1. Slug-specific override (custom SVG keyed by slug)
 *   2. The dashicon class scraped from the badge markup
 *   3. The awards star fallback inside the renderer
 *
 * @param string $slug     Badge slug (badge-{slug} from wp.org markup).
 * @param string $dashicon Dashicon name scraped from the same markup, if any.
 * @return string Icon key to pass to wcu_get_dashicon_svg().
 */
function wcu_resolve_badge_icon( $slug, $dashicon ) {
	// Slugs whose wp.org markup has NO `dashicons-{name}` class because
	// wp.org renders them via a CSS background-image data-URI. Each maps
	// to a glyph we ship in wcu_get_dashicon_svg() — either the verbatim
	// wp.org artwork (campus-connect / credits-* with their own viewBoxes)
	// or a close dashicons stand-in for the rest.
	$slug_overrides = array(
		'campus-connect-participant' => 'campus-connect-participant',
		'credits-graduate'           => 'credits-graduate',
		'credits-mentor'             => 'credits-mentor',
		// Background-image badges with no bundled artwork yet — pick the
		// closest dashicon glyph until we embed the real path data.
		'performance-team'           => 'dashboard',
		'performance-contributor'    => 'dashboard',
		'core-performance-team'      => 'dashboard',
		'core-performance-contributor' => 'dashboard',
		'playground'                 => 'admin-tools',
		'playground-contributor'     => 'admin-tools',
		'core-ai-team'               => 'lightbulb',
		'core-ai-contributor'        => 'lightbulb',
		'buddypress'                 => 'buddicons-buddypress-logo',
		'buddypress-contributor'     => 'buddicons-buddypress-logo',
		'openverse'                  => 'screenoptions',
		'openverse-contributor'      => 'screenoptions',
		// Some wp.org slugs use the team's broader name with a different
		// dashicon than the contributor variant — normalize here too.
		'community'                  => $dashicon ?: 'groups',
		'community-team'             => $dashicon ?: 'groups',
		'community-contributor'      => $dashicon ?: 'groups',
	);

	if ( isset( $slug_overrides[ $slug ] ) ) {
		return $slug_overrides[ $slug ];
	}

	return ! empty( $dashicon ) ? $dashicon : '';
}

/**
 * Echo a dashicon SVG.
 *
 * @param string $name Dashicon name (no `dashicons-` prefix).
 * @param array  $args Optional rendering args. See wcu_get_dashicon_svg().
 * @return void
 */
function wcu_dashicon_svg( $name, $args = array() ) {
	echo wcu_get_dashicon_svg( $name, $args ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- Safe SVG built from a fixed lookup table.
}

/**
 * Get a list of social profile URLs from theme mods.
 *
 * Customizer keys: wcu_social_twitter, wcu_social_facebook, wcu_social_linkedin,
 * wcu_social_instagram, wcu_social_github, wcu_social_youtube, wcu_social_wordpress.
 *
 * @return array<string,string> Map of network key to URL, in display order.
 */
function wcu_get_social_links() {
	$networks = array( 'twitter', 'facebook', 'linkedin', 'instagram', 'youtube', 'github', 'wordpress' );
	$links    = array();

	foreach ( $networks as $network ) {
		$url = get_theme_mod( 'wcu_social_' . $network, '' );
		if ( ! empty( $url ) ) {
			$links[ $network ] = esc_url( $url );
		}
	}

	return $links;
}

/**
 * Posted-on meta string for the current post (date + author).
 *
 * @return string Escaped meta HTML.
 */
function wcu_get_posted_meta() {
	$time_string = sprintf(
		'<time class="entry-date published updated" datetime="%1$s">%2$s</time>',
		esc_attr( get_the_date( DATE_W3C ) ),
		esc_html( get_the_date() )
	);

	$author = sprintf(
		/* translators: %s: post author display name. */
		esc_html__( 'By %s', 'wcuganda' ),
		'<a class="entry-author" href="' . esc_url( get_author_posts_url( get_the_author_meta( 'ID' ) ) ) . '">' . esc_html( get_the_author() ) . '</a>'
	);

	return '<span class="entry-date-wrap">' . $time_string . '</span> <span class="entry-author-wrap">' . $author . '</span>';
}

/**
 * Render the wp.org "Powered by WordPress" attribution used in the footer.
 *
 * @return string HTML string.
 */
function wcu_get_powered_by() {
	return sprintf(
		/* translators: 1: opening anchor tag, 2: closing anchor tag. */
		esc_html__( 'Proudly part of the global %1$sWordPress%2$s community.', 'wcuganda' ),
		'<a href="' . esc_url( 'https://wordpress.org/' ) . '" rel="nofollow noopener">',
		'</a>'
	);
}
